create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text unique,full_name text,avatar_url text,role text not null default 'student' check(role in('admin','student','partner')),created_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),name text not null,category text not null check(category in('تنجيد','خياطة','تفصيل')),price numeric,image_url text,description text,created_at timestamptz not null default now());
create table if not exists public.work_gallery(id uuid primary key default gen_random_uuid(),image_url text not null,caption text,created_at timestamptz not null default now());
create table if not exists public.social_links(id bigint generated by default as identity primary key,platform text not null unique,url text not null,is_active boolean not null default true);
create table if not exists public.client_requests(id bigint generated by default as identity primary key,client_name text not null,phone text not null,service_type text not null,message text,status text not null default 'new' check(status in('new','contacted','in_progress','closed','cancelled')),created_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email,full_name) values(new.id,new.email,new.raw_user_meta_data->>'full_name') on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
alter table public.profiles enable row level security; alter table public.products enable row level security; alter table public.work_gallery enable row level security; alter table public.social_links enable row level security; alter table public.client_requests enable row level security;
drop policy if exists profiles_self on public.profiles; create policy profiles_self on public.profiles for select using(auth.uid()=id or public.is_admin());
drop policy if exists products_public_read on public.products; create policy products_public_read on public.products for select using(true); drop policy if exists products_admin_write on public.products; create policy products_admin_write on public.products for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists gallery_public_read on public.work_gallery; create policy gallery_public_read on public.work_gallery for select using(true); drop policy if exists gallery_admin_write on public.work_gallery; create policy gallery_admin_write on public.work_gallery for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists socials_public_read on public.social_links; create policy socials_public_read on public.social_links for select using(is_active=true); drop policy if exists socials_admin_write on public.social_links; create policy socials_admin_write on public.social_links for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists requests_public_insert on public.client_requests; create policy requests_public_insert on public.client_requests for insert with check(char_length(client_name) between 2 and 120 and char_length(phone) between 6 and 30 and char_length(service_type) between 2 and 80 and coalesce(char_length(message),0)<=4000); drop policy if exists requests_admin_read on public.client_requests; create policy requests_admin_read on public.client_requests for select using(public.is_admin()); drop policy if exists requests_admin_update on public.client_requests; create policy requests_admin_update on public.client_requests for update using(public.is_admin()) with check(public.is_admin());
